package vn.tuan.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import vn.tuan.entity.*;import vn.tuan.repository.*;import java.math.*;import java.time.*;
@Service @RequiredArgsConstructor public class QuoteService {
 private final CarrierRepository carriers;private final PromotionRepository promotions;
 public record Quote(BigDecimal subtotal,BigDecimal shipping,BigDecimal discount,BigDecimal total,Carrier carrier,Promotion promotion){}
 public Quote calculate(BigDecimal subtotal,Integer shopId,Integer carrierId,String code){Carrier carrier=carrierId==null?carriers.findAll().stream().filter(c->Boolean.TRUE.equals(c.getIsActive()) && (c.getShop()==null || c.getShop().getId().equals(shopId))).findFirst().orElseThrow(()->new IllegalArgumentException("Chưa có đơn vị vận chuyển")):carriers.findById(carrierId).orElseThrow();OrderRules.require(Boolean.TRUE.equals(carrier.getIsActive()) && (carrier.getShop()==null || carrier.getShop().getId().equals(shopId)),"Đơn vị giao hàng không áp dụng cho quán");BigDecimal discount=BigDecimal.ZERO;Promotion p=null;if(code!=null && !code.isBlank()){p=promotions.findByCodeIgnoreCase(code.trim()).orElseThrow(()->new IllegalArgumentException("Mã giảm giá không tồn tại"));OrderRules.require(Boolean.TRUE.equals(p.getIsActive()) && (p.getShop()==null || p.getShop().getId().equals(shopId)) && (p.getExpiresAt()==null || p.getExpiresAt().isAfter(LocalDateTime.now())),"Mã giảm giá hết hạn hoặc không áp dụng cho chi nhánh");OrderRules.require(p.getMinOrderAmount()==null || subtotal.compareTo(p.getMinOrderAmount())>=0,"Chưa đạt giá trị đơn tối thiểu");BigDecimal base="SHIPPING".equals(p.getType())?carrier.getBaseFee():subtotal;discount=base.multiply(BigDecimal.valueOf(p.getDiscountPercent())).divide(BigDecimal.valueOf(100),0,RoundingMode.DOWN);if(p.getMaxDiscount()!=null)discount=discount.min(p.getMaxDiscount());discount=discount.min(base);}return new Quote(subtotal,carrier.getBaseFee(),discount,subtotal.add(carrier.getBaseFee()).subtract(discount),carrier,p);}
}
